update estimulos_rft_base e set nombre = 'El queso' from clases_rft_base c where e.clase_base_id = c.id and c.programa_base_id = (select id from programas_base where clinica_id is null and nombre = 'Vincular Mutuamente Relaciones Espaciales') and c.nombre = 'Clase 24' and e.posicion = 'A';
update estimulos_rft_base e set nombre = 'El pan' from clases_rft_base c where e.clase_base_id = c.id and c.programa_base_id = (select id from programas_base where clinica_id is null and nombre = 'Vincular Mutuamente Relaciones Espaciales') and c.nombre = 'Clase 24' and e.posicion = 'B';

update programas_base set
  materiales = replace(materiales,
    'La relación se presenta solo de forma verbal, con imágenes sueltas de los elementos, sin colocarlas en la escena, de forma que ninguna disposición física indique la relación. En cada ensayo se ofrecen como opciones los dos elementos nombrados y un tercero (distractor) de otra relación del grupo, para que la respuesta dependa de la clave relacional y no de haber oído el nombre.',
    'La relación se presenta solo de forma verbal. Las opciones también son verbales: en cada ensayo se dicen, una a una, las palabras de los dos elementos nombrados y de un tercero (distractor) de otra relación del grupo, y el alumno elige una (en la tableta, tocando su tarjeta de audio). Así ninguna disposición física indica la relación y la respuesta depende de la clave relacional, no de haber oído el nombre. En la mitad de las clases la frase va en orden invertido («Debajo de la silla está la pelota»), para que la respuesta no sea siempre el mismo nombre de la frase.'),
  instrucciones_terapeuta = replace(instrucciones_terapeuta,
    'Opciones de respuesta: en cada ensayo, las imágenes sueltas de los dos elementos nombrados y de un tercero de otra relación del grupo (ej. gato, mesa y coche). Así no basta con elegir el elemento que se ha oído: hay que responder a la clave relacional.',
    'Opciones de respuesta: en cada ensayo, diga una a una las palabras de los dos elementos nombrados y de un tercero de otra relación del grupo (ej. «el gato», «la mesa», «el coche»); el alumno elige una. Así no basta con elegir el elemento que se ha oído: hay que responder a la clave relacional. En la mitad de las clases la relación se enuncia en orden invertido («Debajo de la silla está la pelota»).')
where clinica_id is null and nombre = 'Vincular Mutuamente Relaciones Espaciales';

commit;
